import { NavLink, Outlet } from 'react-router-dom'
import { PageHeader } from '@/features/shell/PageHeader'
import { clsx } from 'clsx'

const MARKETPLACE_TABS = [
  { path: '/marketplace/apps', label: 'Apps' },
  { path: '/marketplace/templates', label: 'Templates' },
  { path: '/marketplace/funds', label: 'Funds' },
  { path: '/marketplace/secondary', label: 'Secondary' },
  { path: '/marketplace/developer', label: 'Developer' },
]

export function MarketplaceLayout() {
  return (
    <div className="flex flex-col h-full overflow-hidden">
      <PageHeader title="Marketplace" />
      <nav className="flex border-b border-border px-4 bg-surface shrink-0 overflow-x-auto">
        {MARKETPLACE_TABS.map((tab) => (
          <NavLink key={tab.path} to={tab.path}
            className={({ isActive }) => clsx('px-4 py-2.5 text-sm whitespace-nowrap border-b-2 transition-colors',
              isActive ? 'border-accent text-accent font-medium' : 'border-transparent text-muted-foreground hover:text-foreground')}>
            {tab.label}
          </NavLink>
        ))}
      </nav>
      <div className="flex-1 overflow-hidden"><Outlet /></div>
    </div>
  )
}
